import sys
from collections import defaultdict

def find_earliest_train(N, M, trains):
    # Build adjacency list for graph
    graph = defaultdict(list)
    for x, s, t, l in trains:
        real_t = t + l
        graph[x].append((x + 1, s + l, real_t + l))

    # Bellman-Ford algorithm to find shortest paths with negative weights
    distances = [float('inf')] * N
    distances[0] = 0

    # Relax edges repeatedly
    for _ in range(N - 1):
        updated = False
        for x, s, t in trains:
            real_s = s + t
            for nx, ns, nt in graph[x]:
                if distances[x] != float('inf') and distances[x] + nt < distances[nx]:
                    distances[nx] = distances[x] + nt
                    updated = True
        if not updated:
            break

    # Check if there's a negative cycle
    for x, s, t in trains:
        real_s = s + t
        for nx, ns, nt in graph[x]:
            if distances[x] != float('inf') and distances[x] + nt < distances[nx]:
                return "impossible"

    # Find the earliest time to book a train
    min_time = float('inf')
    for i in range(N):
        for _, s, _ in trains:
            if distances[i] == float('inf'):
                continue
            for nx, ns, nt in graph[i]:
                if nt >= 1800 and s <= nt - 1800:
                    min_time = min(min_time, s)

    if min_time == float('inf'):
        return "impossible"
    else:
        return min_time

